/// <summary>
/// MPJ_5012_RebateProcess
/// Service class to run the update of Rebate Item groups by adding new items
/// </summary>
class METRebateExcludeForPaymentService extends SysOperationServiceBase
{
    const real  RetryNum = 3;
}

Method.Source:
    /// <summary>
    /// MPJ_5012_RebateProcess
    /// Method to exclude the items of the rebate deal for payment.
    /// </summary>
    /// <param name = "_contract"> METRebateExcludeForPaymentContract </param>
    public void processOperation(METRebateExcludeForPaymentContract _contract)
    {
        FeatureManagementState      featureManagementState;

        select firstonly1 featureManagementState where featureManagementState.Name == METConstants::UnifiedPricingFeature;
        if(featureManagementState.IsEnabled == NoYes::Yes)
        {
            this.unifiedPricingEnabledExclude(_contract);
        }
        else
        {
            this.unifiedPricingNotEnabledExclude(_contract);
        }
    }

    protected void unifiedPricingEnabledExclude(METRebateExcludeForPaymentContract _contract)
    {
        TAMRebateDeal               rebateDealContract;
        QueryRun                    queryRun;
        QueryBuildDataSource        qbdsRebateTrans, qbdsRebateTable, qbdsExcludeForPayment, qbdsMetInventTable;

        const Amount rebateAmountMultiplier = 0.0;

        Query query = new Query();
        rebateDealContract  =   _contract.parmTAMRebateDeal();

        qbdsRebateTrans = query.addDataSource(tableNum(TAMRebateTrans));
        qbdsRebateTrans.addSortField(fieldNum(TAMRebateTrans, RebateId), SortOrder::Ascending);

        qbdsRebateTable = qbdsRebateTrans.addDataSource(tableNum(TAMRebateTable));
        qbdsRebateTable.relations(false);
        qbdsRebateTable.fetchMode(QueryFetchMode::One2One);
        qbdsRebateTable.addLink(fieldNum(TAMRebateTrans, RebateId), fieldNum(TAMRebateTable, RebateId));
        qbdsRebateTable.addRange(fieldNum(TAMRebateTable, RebateDeal)).value(SysQuery::value(rebateDealContract.RecId));

        qbdsMetInventTable = qbdsRebateTable.addDataSource(tableNum(METInventTable));
        qbdsMetInventTable.relations(false);
        qbdsMetInventTable.fetchMode(QueryFetchMode::One2One);
        qbdsMetInventTable.addRange(fieldNum(METInventTable, ExcludeForPayment)).value(queryValue(NoYes::Yes));

        qbdsExcludeForPayment = qbdsRebateTable.addDataSource(tableNum(METExcludeForPaymentProducts));
        qbdsExcludeForPayment.relations(false);
        qbdsExcludeForPayment.fetchMode(QueryFetchMode::One2One);
        qbdsExcludeForPayment.joinMode(JoinMode::ExistsJoin);
        qbdsExcludeForPayment.addRange(fieldNum(METExcludeForPaymentProducts, RuleId)).value(strFmt('(((%1.%2 = %3.%4) && (%1.%5 = %6.%7)))||(%6.%7 = %8.%9)',
            qbdsExcludeForPayment.name(),
            fieldStr(METExcludeForPaymentProducts, RuleId),
            qbdsRebateTable.name(),
            fieldStr(TAMRebateTable, PricingRuleLine),
            fieldStr(METExcludeForPaymentProducts, ItemId),
            qbdsRebateTrans.name(),
            fieldStr(TAMRebateTrans, ItemId),
            qbdsMetInventTable.name(),
            fieldStr(METInventTable, ItemId)));

        queryRun = new QueryRun(query);

        while(queryRun.next())
        {
            TAMRebateTrans  rebateTrans     =   queryRun.get(tableNum(TAMRebateTrans));

            try
            {
                ttsbegin;
                rebateTrans.selectForUpdate(true);
                rebateTrans.RebateAmount    =   rebateTrans.RebateAmount * rebateAmountMultiplier;
                rebateTrans.Claimed         =   NoYes::No;
                rebateTrans.modifiedField(fieldNum(TAMRebateTrans, Claimed));
                if(rebateTrans.validateWrite())
                {
                    rebateTrans.update(true);
                }
                ttscommit;
            }
            catch(Exception::UpdateConflict)
            {
                Info("@MET:METExcludeUpdateConflict", rebateTrans.ItemId);
                throw Exception::UpdateConflictNotRecovered;
            }
            catch(Exception::Deadlock)
            {
                if (xSession::currentRetryCount() >= RetryNum)
                {
                    throw Exception::UpdateConflictNotRecovered;
                }
                retry;
            }
            catch(Exception::CLRError)
            {
                System.Exception netExcepn;
                info("@MET:METRebateCLRException");
                netExcepn = CLRInterop::getLastException();
                info(netExcepn.ToString());
            }
            catch(Exception::Error)
            {
                Info("@MET:METRebateError");
            }
        }
    }

    protected void unifiedPricingNotEnabledExclude(METRebateExcludeForPaymentContract _contract)
    {
        TAMRebateDeal               rebateDealContract;
        TAMRebateTrans              rebateTrans;
        
        Query                       query;
        QueryRun                    queryRun;
        QueryBuildDataSource        qbdsRebateTrans, qbdsRebateGroupLink, qbdsInventTable, qbdsRebateTable;

        const Amount rebateAmountMultiplier = 0.0;

        query = new Query();
        rebateDealContract  =   _contract.parmTAMRebateDeal();

        qbdsRebateTrans = query.addDataSource(tableNum(TAMRebateTrans));
        qbdsRebateTrans.addSortField(fieldNum(TAMRebateTrans, RebateId), SortOrder::Ascending);

        qbdsRebateTable = qbdsRebateTrans.addDataSource(tableNum(TAMRebateTable));
        qbdsRebateTable.relations(false);
        qbdsRebateTable.fetchMode(QueryFetchMode::One2One);
        qbdsRebateTable.addLink(fieldNum(TAMRebateTrans, RebateId), fieldNum(TAMRebateTable, RebateId));
        qbdsRebateTable.addRange(fieldNum(TAMRebateTable, RebateDeal)).value(SysQuery::value(rebateDealContract.RecId));
       
        qbdsInventTable = qbdsRebateTrans.addDataSource(tableNum(InventTable));
        qbdsInventTable.relations(false);
        qbdsInventTable.fetchMode(QueryFetchMode::One2One);
        qbdsInventTable.addLink(fieldNum(TAMRebateTrans, ItemId), fieldNum(InventTable, ItemId));

        qbdsRebateGroupLink = qbdsRebateTable.addDataSource(tableNum(TAMRebateGroupLink));
        qbdsRebateGroupLink.relations(false);
        qbdsRebateGroupLink.fetchMode(QueryFetchMode::One2One);
        qbdsRebateGroupLink.addLink(fieldNum(TAMRebateTable, ItemRelation), fieldNum(TAMRebateGroupLink,RebateGroupId));
        qbdsRebateGroupLink.addRange(fieldNum(TAMRebateGroupLink, ModuleInventCustVend)).value(enum2Str(ModuleInventCustVend::Invent));
        qbdsRebateGroupLink.addRange(fieldnum(TAMRebateGroupLink, METExcludeForPayment)).value(enum2Str(NoYes::Yes));
        qbdsRebateGroupLink.addRange(fieldnum(TAMRebateGroupLink, RefRecId)).value(strFmt('((%1.%2 = %3.%4) && (%1.%5 = %3.%6))',
            qbdsRebateGroupLink.name(),
            fieldStr(TAMRebateGroupLink, RefRecId),
            qbdsInventTable.name(),
            fieldStr(InventTable, RecId),
            fieldStr(TAMRebateGroupLink, RefTableId),
            fieldStr(InventTable, TableId)));

        queryRun = new QueryRun(query);

        while(queryRun.next())
        {
            rebateTrans     =   queryRun.get(tableNum(TAMRebateTrans));

            try
            {
                ttsbegin;
                rebateTrans.selectForUpdate(true);
                rebateTrans.RebateAmount    =   rebateTrans.RebateAmount * rebateAmountMultiplier;
                rebateTrans.Claimed         =   NoYes::No;
                rebateTrans.modifiedField(fieldNum(TAMRebateTrans, Claimed));
                if(rebateTrans.validateWrite())
                {
                    rebateTrans.update(true);
                }
                ttscommit;
            }
            catch(Exception::UpdateConflict)
            {
                Info("@MET:METExcludeUpdateConflict", rebateTrans.ItemId);
                throw Exception::UpdateConflictNotRecovered;
            }
            catch(Exception::Deadlock)
            {
                if (xSession::currentRetryCount() >= RetryNum)
                {
                    throw Exception::UpdateConflictNotRecovered;
                }
                retry;
            }
            catch(Exception::CLRError)
            {
                System.Exception netExcepn;
                info("@MET:METRebateCLRException");
                netExcepn = CLRInterop::getLastException();
                info(netExcepn.ToString());
            }
            catch(Exception::Error)
            {
                Info("@MET:METRebateError");
            }
        }

    }
